function updatePlanetLineGraph() {
  const selectEl = document.getElementById('planet-selector');
  if (!selectEl) return;
  const planetId = selectEl.value;
  const planet = availablePlanets.find(p => p.id === planetId) || availablePlanets[0];

  // Update info badge
  const infoEl = document.getElementById('planet-info-badge');
  if (infoEl) {
    infoEl.innerHTML = '<strong>' + planet.name + '</strong> &bull; Host: <em>' + planet.host + '</em> &bull; Type: ' + planet.type + ' &bull; Distance from Earth: ' + planet.dist_earth + ' ly';
  }

  const [px, py, pz] = planet.coords;
  const distList = [];

  for (let i = 0; i < allCatalogStars.length; i++) {
    const s = allCatalogStars[i];
    const dx = s.x - px;
    const dy = s.y - py;
    const dz = s.z - pz;
    const dist = Math.sqrt(dx * dx + dy * dy + dz * dz);

    // Filter out host star itself if distance is nearly 0
    if (dist > 0.1) {
      distList.push({
        name: s.n,
        distPlanet: Math.round(dist * 100) / 100,
        distEarth: Math.round(s.d * 100) / 100
      });
    }
  }

  distList.sort((a, b) => a.distPlanet - b.distPlanet);
  const topStars = distList.slice(0, 15);

  const starNames = topStars.map(s => s.name);
  const planetDists = topStars.map(s => s.distPlanet);
  const earthDists = topStars.map(s => s.distEarth);

  const tracePlanet = {
    x: starNames,
    y: planetDists,
    type: 'scatter',
    mode: 'lines+markers',
    name: 'Distance from ' + planet.name.split(' (')[0],
    line: { color: '#d84315', width: 3 },
    marker: { size: 8, color: '#d84315', symbol: 'circle' },
    hovertemplate: '<b>%{x}</b><br>Distance from ' + planet.name.split(' (')[0] + ': %{y} ly<extra></extra>'
  };

  const traceEarth = {
    x: starNames,
    y: earthDists,
    type: 'scatter',
    mode: 'lines+markers',
    name: 'Distance from Earth',
    line: { color: '#0d47a1', width: 2, dash: 'dash' },
    marker: { size: 6, color: '#0d47a1', symbol: 'diamond' },
    hovertemplate: '<b>%{x}</b><br>Distance from Earth: %{y} ly<extra></extra>'
  };

  const layout = {
    title: {
      text: 'Distances to 15 Nearest Stars: ' + planet.name.split(' (')[0] + ' vs. Earth',
      font: { color: 'navy', size: 16 }
    },
    xaxis: {
      title: 'Nearest Stars (Ranked by Closeness to Selected Planet)',
      tickangle: -35,
      automargin: true
    },
    yaxis: {
      title: 'Distance (Light-Years)',
      zeroline: true,
      gridcolor: '#e0e0e0'
    },
    legend: {
      orientation: 'h',
      y: 1.15,
      x: 0.2
    },
    margin: { t: 60, b: 90, l: 50, r: 20 },
    paper_bgcolor: '#ffffff',
    plot_bgcolor: '#fbfcfd'
  };

  if (window.Plotly) {
    Plotly.react('planet-line-plot', [tracePlanet, traceEarth], layout, { responsive: true });
  }
}

function initPlanetSelector() {
  const selectEl = document.getElementById('planet-selector');
  if (!selectEl) return;

  selectEl.innerHTML = '';
  availablePlanets.forEach(p => {
    const opt = document.createElement('option');
    opt.value = p.id;
    opt.textContent = p.name + ' (' + (p.dist_earth === 0 ? 'Solar System' : p.dist_earth + ' ly away') + ')';
    if (p.id === 'proxima_b') opt.selected = true;
    selectEl.appendChild(opt);
  });

  selectEl.addEventListener('change', updatePlanetLineGraph);
  updatePlanetLineGraph();
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initPlanetSelector);
} else {
  initPlanetSelector();
}
